11	function Test-AdrBoundFilePath {
12	    param([string]$Root, [string]$Relative)
13	    if ($Relative -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._/-]*$' -or
14	        $Relative.EndsWith('/', [StringComparison]::Ordinal) -or
15	        $Relative.Contains('//') -or $Relative -cmatch '(^|/)[.]{1,2}(/|$)') {
16	        return $false
17	    }
18	    $rootItem = Get-Item -LiteralPath $Root -Force -ErrorAction Stop
19	    if (-not $rootItem.PSIsContainer -or
20	        ($rootItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
21	        return $false
22	    }
23	    $current = $Root
24	    $components = $Relative.Split('/')
25	    for ($index = 0; $index -lt $components.Length; $index++) {
26	        $component = $components[$index]
27	        $matches = @(Get-ChildItem -LiteralPath $current -Force -ErrorAction Stop |
28	            Where-Object { [string]::Equals($_.Name, $component, [StringComparison]::Ordinal) })
29	        if ($matches.Count -ne 1) { return $false }
30	        $item = $matches[0]
31	        if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
32	            return $false
33	        }
34	        if ($index -lt $components.Length - 1) {
35	            if (-not $item.PSIsContainer) { return $false }
36	        }
37	        else {
38	            if ($item -isnot [IO.FileInfo] -or $item.PSIsContainer -or
39	                ($item.Attributes -band [IO.FileAttributes]::Device) -ne 0) {
40	                return $false
41	            }
42	            if (-not $IsWindows) {
43	                # FileInfo/Leaf also describe POSIX devices; require lstat type.
44	                $statProperty = $item.PSObject.Properties['UnixStat']
45	                if ($null -eq $statProperty -or $null -eq $statProperty.Value -or
46	                    -not [string]::Equals([string]$statProperty.Value.ItemType,
47	                        'File', [StringComparison]::Ordinal)) {
48	                    return $false
49	                }
50	            }
51	        }
52	        $current = $item.FullName
53	    }
54	    # The consuming hash/read must still fail closed on access/open failure.
55	    return $true
56	}
