58	# RT-20260908-004: the same restricted byte-oriented line grammar as Bash.
59	function Get-AdrDeclaredPaths {
60	    param([string]$DesignPath)
61	    # Latin-1 preserves each byte, including a BOM; the grammar is ASCII only.
62	    # ReadAllText would strip a BOM and diverge from LC_ALL=C awk at fences.
63	    $text = [Text.Encoding]::GetEncoding(28591).GetString([IO.File]::ReadAllBytes($DesignPath))
64	    $paths = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
65	    function Get-AdrRunWidth([string]$Line, [int]$Start, [char]$Delimiter) {
66	        $width = 0
67	        while (($Start + $width) -lt $Line.Length -and $Line[$Start + $width] -ceq $Delimiter) { $width++ }
68	        return $width
69	    }
70	    function Test-AdrRunEscaped([string]$Line, [int]$Start) {
71	        $slashes = 0
72	        while ($Start -gt 0 -and $Line[$Start - 1] -ceq [char]92) { $slashes++; $Start-- }
73	        return (($slashes % 2) -ne 0)
74	    }
75	    $fence = [char]0
76	    $fenceWidth = 0
77	    foreach ($rawLine in $text.Split([char]10)) {
78	        $line = $rawLine
79	        if ($line.Length -gt 0 -and $line[$line.Length - 1] -ceq [char]13) {
80	            $line = $line.Substring(0, $line.Length - 1)
81	        }
82	        $indent = 0
83	        while ($indent -lt $line.Length -and $line[$indent] -ceq [char]32) { $indent++ }
84	        $rest = $line.Substring($indent)
85	        $first = [char]0
86	        if ($rest.Length -gt 0) { $first = $rest[0] }
87	        if ($fence -cne [char]0) {
88	            if ($indent -le 3 -and $first -ceq $fence) {
89	                $width = Get-AdrRunWidth $rest 0 $fence
90	                if ($width -ge $fenceWidth -and $rest.Substring($width) -cmatch '^[ \t]*$') {
91	                    $fence = [char]0
92	                }
93	            }
94	            continue
95	        }
96	        if ($indent -ge 4 -or $first -ceq [char]9) { continue }
97	        if ($first -ceq [char]96 -or $first -ceq [char]126) {
98	            $width = Get-AdrRunWidth $rest 0 $first
99	            if ($width -ge 3) { $fence = $first; $fenceWidth = $width; continue }
100	        }
101	        $i = 0
102	        while ($i -lt $line.Length) {
103	            if ($line[$i] -cne [char]96) { $i++; continue }
104	            $width = Get-AdrRunWidth $line $i ([char]96)
105	            if (Test-AdrRunEscaped $line $i) { $i += $width; continue }
106	            $j = $i + $width
107	            $closed = $false
108	            while ($j -lt $line.Length) {
109	                if ($line[$j] -cne [char]96) { $j++; continue }
110	                $closeWidth = Get-AdrRunWidth $line $j ([char]96)
111	                if ($closeWidth -eq $width -and -not (Test-AdrRunEscaped $line $j)) {
112	                    $closed = $true
113	                    break
114	                }
115	                $j += $closeWidth
116	            }
117	            if (-not $closed) { break }
118	            $value = $line.Substring($i + $width, $j - $i - $width)
119	            if ($width -eq 1 -and $value -cmatch '^docs/adr/[0-9]{4}-[a-z0-9][a-z0-9-]*[.]md$') {
120	                [void]$paths.Add($value)
121	            }
122	            $i = $j + $width
123	        }
124	    }
125	    [string[]]$result = @($paths)
126	    [Array]::Sort($result, [StringComparer]::Ordinal)
127	    return $result
128	}
129	# Return JSON as a scalar to preserve both empty and singleton arrays.
130	function Get-AdrPrecheckInputsJson {
131	    param([string]$Root, [string]$DesignRelative, [string]$ExpectedDesign)
132	    if ($ExpectedDesign -cnotmatch '^[0-9a-f]{64}$' -or
133	        -not (Test-AdrBoundFilePath $Root $DesignRelative)) {
134	        Fail 'unsafe design ADR authority'
135	    }
136	    $designPath = Join-Path $Root $DesignRelative
137	    $before = (Get-FileHash -LiteralPath $designPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
138	    if ($before -cne $ExpectedDesign) { Fail 'design changed before ADR collection' }
139	    $entries = [Collections.Generic.List[object]]::new()
140	    foreach ($path in @(Get-AdrDeclaredPaths $designPath)) {
141	        if (-not (Test-AdrBoundFilePath $Root $path)) { Fail "unsafe ADR input: $path" }
142	        $digest = (Get-FileHash -LiteralPath (Join-Path $Root $path) -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
143	        if ($digest -cnotmatch '^[0-9a-f]{64}$') { Fail 'invalid ADR digest' }
144	        $entries.Add([ordered]@{path=$path;sha256=$digest})
145	    }
146	    if (-not (Test-AdrBoundFilePath $Root $DesignRelative)) { Fail 'design path changed during collection' }
147	    $after = (Get-FileHash -LiteralPath $designPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
148	    if ($after -cne $ExpectedDesign) { Fail 'design changed during ADR collection' }
149	    return ConvertTo-Json -InputObject ($entries.ToArray()) -Depth 4 -Compress
150	}
151	# Only extension material uses this canonical order; legacy evidence is untouched.
152	function Get-AdrLayerJson {
153	    param($Layers)
154	    if ($null -eq $Layers -or ($Layers -isnot [pscustomobject] -and
155	        $Layers -isnot [Collections.IDictionary])) { Fail 'invalid layer object' }
156	    $names = if ($Layers -is [Collections.IDictionary]) { @($Layers.Keys) }
157	             else { @($Layers.PSObject.Properties.Name) }
158	    $expected = @('frontend-spec.md','infra-spec.md','security-spec.md','ux-spec.md')
159	    if ($names.Count -ne 0 -and $names.Count -ne 4) { Fail 'invalid layer key count' }
160	    foreach ($name in $names) {
161	        if ($name -isnot [string] -or $expected -cnotcontains $name) { Fail 'invalid layer key' }
162	    }
163	    $canonical = [ordered]@{}
164	    if ($names.Count -gt 0) {
165	        foreach ($name in $expected) {
166	            if ($names -cnotcontains $name) { Fail 'missing layer key' }
167	            $value = if ($Layers -is [Collections.IDictionary]) { $Layers[$name] }
168	                     else { $Layers.PSObject.Properties[$name].Value }
169	            if ($value -isnot [string] -or $value.Length -ne 64 -or $value -cnotmatch '^[0-9a-f]{64}$') {
170	                Fail 'invalid layer digest'
171	            }
172	            $canonical[$name] = $value
173	        }
174	    }
175	    return ConvertTo-Json -InputObject $canonical -Compress
176	}
177	function Get-AdrHistoryJson {
178	  param($Entries)
179	  if ($Entries -isnot [array]) { Fail 'invalid persisted ADR array' }
180	  $normalized = [Collections.Generic.List[object]]::new()
181	  $previous = $null
182	  foreach ($entry in $Entries) {
183	    if ($null -eq $entry -or $entry -isnot [pscustomobject]) { Fail 'invalid persisted ADR entry' }
184	    $keys = @($entry.PSObject.Properties.Name)
185	    if ($keys.Count -ne 2 -or $keys -cnotcontains 'path' -or $keys -cnotcontains 'sha256' -or
186	        $entry.path -isnot [string] -or $entry.sha256 -isnot [string] -or
187	        $entry.path -cnotmatch '\Adocs/adr/[0-9]{4}-[a-z0-9][a-z0-9-]*[.]md\z' -or
188	        $entry.sha256.Length -ne 64 -or $entry.sha256 -cnotmatch '\A[0-9a-f]{64}\z') {
189	      Fail 'invalid persisted ADR fields'
190	    }
191	    if ($null -ne $previous -and [StringComparer]::Ordinal.Compare($previous, $entry.path) -ge 0) {
192	      Fail 'persisted ADR entries must be sorted and unique'
193	    }
194	    $previous = $entry.path
195	    $normalized.Add([ordered]@{path=$entry.path;sha256=$entry.sha256})
196	  }
197	  return ConvertTo-Json -InputObject ($normalized.ToArray()) -Compress -Depth 4
198	}
199	function Get-AdrPreviousRoundJson {
200	  param([string]$RepoRoot, $Prior, [string]$FeatureName, [long]$AttemptNumber, [long]$RoundNumber)
201	  $relativeRoot = "reports/impl-review/$FeatureName/attempt-$AttemptNumber/round-$RoundNumber"
202	  $precheckRelative = "$relativeRoot/precheck-result.json"
203	  if (-not (Test-AdrBoundFilePath $RepoRoot "$relativeRoot/impl-review-contract.json") -or
204	      -not (Test-AdrBoundFilePath $RepoRoot $precheckRelative)) { Fail 'unsafe previous ADR evidence path' }
205	  $precheckPath = Join-Path $RepoRoot $precheckRelative
206	  $precheckHash = (Get-FileHash -LiteralPath $precheckPath -Algorithm SHA256).Hash.ToLowerInvariant()
207	  $precheck = Get-Content -LiteralPath $precheckPath -Raw | ConvertFrom-Json -NoEnumerate
208	  if ($Prior -isnot [pscustomobject] -or $precheck -isnot [pscustomobject]) {
209	    Fail 'previous ADR evidence must contain objects'
210	  }
211	  $priorHasAdr = @($Prior.PSObject.Properties.Name) -ccontains 'adr_inputs'
212	  $precheckHasAdr = @($precheck.PSObject.Properties.Name) -ccontains 'adr_inputs'
213	  if ($priorHasAdr -ne $precheckHasAdr) { Fail 'one-sided previous ADR extension' }
214	  if (-not $priorHasAdr) {
215	    foreach ($reviewer in @($Prior.reviewers)) {
216	      foreach ($entry in @($reviewer.allowed_input_manifest)) {
217	        $relative = Get-ManifestRelativePath ([string]$entry.path) $RepoRoot
218	        if ($relative -is [string] -and $relative.StartsWith('docs/adr/', [StringComparison]::Ordinal)) {
219	          Fail 'legacy previous contract cannot admit ADR inputs'
220	        }
221	      }
222	    }
223	    return $null
224	  }
225	  if ($Prior.schema -cne 'impl-review-contract/v1' -or $Prior.stage -cne 'impl' -or
226	      $Prior.feature -cne $FeatureName -or $Prior.verdict -cne 'NEEDS_WORK' -or
227	      $precheck.schema -cne 'impl-review-precheck/v1' -or $precheck.feature -cne $FeatureName) {
228	    Fail 'invalid previous ADR review identity or verdict'
229	  }
230	  foreach ($document in @($Prior, $precheck)) {
231	    if ($document.attempt -isnot [long] -or $document.round -isnot [long] -or
232	        $document.attempt -ne $AttemptNumber -or $document.round -ne $RoundNumber) {
233	      Fail 'previous ADR attempt/round differs from directory'
234	    }
235	  }
236	  $recorded = Get-AdrHistoryJson $precheck.adr_inputs
237	  if ((Get-AdrHistoryJson $Prior.adr_inputs) -cne $recorded) { Fail 'previous ADR sets disagree' }
238	  foreach ($field in @('design_sha256','requirements_sha256','acceptance_sha256')) {
239	    if ($precheck.$field -isnot [string] -or $precheck.$field.Length -ne 64 -or
240	        $precheck.$field -cnotmatch '\A[0-9a-f]{64}\z' -or
241	        $Prior.$field -isnot [string] -or $Prior.$field -cne $precheck.$field) {
242	      Fail 'previous ADR core pins disagree'
243	    }
244	  }
245	  $layers = Get-AdrLayerJson $precheck.layer_sha256
246	  if ((Get-AdrLayerJson $Prior.layer_sha256) -cne $layers) { Fail 'previous ADR layer pins disagree' }
247	  $reviewers = @($Prior.reviewers)
248	  if ($reviewers.Count -ne 2) { Fail 'previous ADR review requires two reviewers' }
249	  foreach ($role in @('impl-reviewer-a','impl-reviewer-b')) {
250	    $matches = @($reviewers | Where-Object { $_.role -is [string] -and $_.role -ceq $role })
251	    if ($matches.Count -ne 1) { Fail 'previous ADR reviewer roles differ' }
252	    $reviewerRelative = "$relativeRoot/$($role.Substring(5)).json"
253	    if (-not (Test-AdrBoundFilePath $RepoRoot $reviewerRelative)) { Fail 'unsafe previous ADR reviewer output' }
254	    $reviewerPath = Join-Path $RepoRoot $reviewerRelative
255	    $reviewerHash = (Get-FileHash -LiteralPath $reviewerPath -Algorithm SHA256).Hash.ToLowerInvariant()
256	    $output = Get-Content -LiteralPath $reviewerPath -Raw | ConvertFrom-Json -NoEnumerate
257	    if ($output -isnot [pscustomobject] -or $output.schema -cne "$role/v1" -or
258	        $output.stage -cne 'impl' -or $output.role -cne $role) {
259	      Fail 'previous ADR reviewer output identity mismatch'
260	    }
261	    foreach ($field in @('run_id','host_session_id')) {
262	      if ($output.$field -isnot [string] -or [string]::IsNullOrWhiteSpace($output.$field) -or
263	          $matches[0].$field -isnot [string] -or $output.$field -cne $matches[0].$field) {
264	        Fail 'previous ADR reviewer output provenance mismatch'
265	      }
266	    }
267	    # Opening a failed round can return before workflow-state's PASS checks.
268	    # Bind actual reviewer output as well as the contract's claimed inputs here.
269	    foreach ($source in @($matches[0], $output)) {
270	      if ($source.allowed_input_manifest -isnot [array]) { Fail 'invalid previous ADR reviewer manifest' }
271	      $entries = @($source.allowed_input_manifest)
272	      $documentPins = [ordered]@{
273	        'requirements.md' = $precheck.requirements_sha256
274	        'acceptance-tests.md' = $precheck.acceptance_sha256
275	      }
276	      foreach ($layer in $precheck.layer_sha256.PSObject.Properties) {
277	        $documentPins[$layer.Name] = $layer.Value
278	      }
279	      foreach ($document in $documentPins.Keys) {
280	        $expectedPath = "specs/$FeatureName/$document"
281	        $bound = @($entries | Where-Object {
282	          $_.path -is [string] -and
283	          (Get-ManifestRelativePath $_.path $RepoRoot) -ceq $expectedPath
284	        })
285	        if ($bound.Count -ne 1 -or $bound[0].sha256 -isnot [string] -or
286	            $bound[0].sha256 -cne $documentPins[$document]) {
287	          Fail "previous ADR reviewer document binding mismatch: $document"
288	        }
289	      }
290	      $pcPins = @($entries | Where-Object { $_.path -is [string] -and $_.path -ceq $precheckRelative })
291	      $designPins = @($entries | Where-Object { $_.path -is [string] -and $_.path -ceq "specs/$FeatureName/design.md" })
292	      if ($pcPins.Count -ne 1 -or $pcPins[0].sha256 -isnot [string] -or $pcPins[0].sha256 -cne $precheckHash -or
293	          $designPins.Count -ne 1 -or $designPins[0].sha256 -isnot [string] -or $designPins[0].sha256 -cne $precheck.design_sha256) {
294	        Fail 'previous ADR reviewer precheck/design binding mismatch'
295	      }
296	      $adrMap = [Collections.Generic.SortedDictionary[string,object]]::new([StringComparer]::Ordinal)
297	      foreach ($entry in $entries) {
298	        if ($entry.path -isnot [string]) { Fail 'invalid previous reviewer path type' }
299	        $relative = Get-ManifestRelativePath $entry.path $RepoRoot
300	        if ($relative -is [string] -and $relative.StartsWith('docs/adr/', [StringComparison]::Ordinal) -and
301	            $entry.path -cne $relative) { Fail 'previous ADR reviewer path must be raw canonical relative' }
302	        if (-not $entry.path.StartsWith('docs/adr/', [StringComparison]::Ordinal)) { continue }
303	        if ($adrMap.ContainsKey($entry.path)) { Fail 'duplicate previous reviewer ADR entry' }
304	        $adrMap.Add($entry.path, [pscustomobject]@{path=$entry.path;sha256=$entry.sha256})
305	      }
306	      if ((Get-AdrHistoryJson @($adrMap.Values)) -cne $recorded) { Fail 'incomplete previous reviewer ADR set' }
307	    }
308	    if (-not (Test-AdrBoundFilePath $RepoRoot $reviewerRelative) -or
309	        (Get-FileHash -LiteralPath $reviewerPath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $reviewerHash) {
310	      Fail 'previous ADR reviewer output changed during validation'
311	    }
312	  }
313	  $material = "$($precheck.design_sha256):$($precheck.requirements_sha256):$($precheck.acceptance_sha256)"
314	  if ($layers -cne '{}') { $material += ':' + $layers }
315	  $material += ':adr_inputs/v1:' + $recorded
316	  $inputHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($material))).ToLowerInvariant()
317	  if ($precheck.input_sha256 -isnot [string] -or $precheck.input_sha256 -cne $inputHash) {
318	    Fail 'previous ADR input hash mismatch'
319	  }
320	  if (-not (Test-AdrBoundFilePath $RepoRoot $precheckRelative) -or
321	      (Get-FileHash -LiteralPath $precheckPath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $precheckHash) {
322	    Fail 'previous ADR precheck changed during validation'
323	  }
324	  # Deliberately do not hash current ADR files against historical failed inputs.
325	  return $recorded
326	}
327	function Fail([string]$Message) { throw "impl-review-precheck: $Message" }
328	function Test-OrdinalEqual([object]$Left, [object]$Right) {
329	  return [string]::Equals([string]$Left, [string]$Right, [StringComparison]::Ordinal)
330	}
331	function Get-ManifestRelativePath([string]$Path, [string]$RepoRoot) {
332	  $normalizedPath = $Path.Replace('\', '/')
333	  $normalizedRoot = $RepoRoot.Replace('\', '/').TrimEnd('/')
334	  if ($normalizedPath.StartsWith("$normalizedRoot/", [StringComparison]::Ordinal)) {
335	    $normalizedPath = $normalizedPath.Substring($normalizedRoot.Length + 1)
336	  } elseif ([IO.Path]::IsPathRooted($Path) -or $normalizedPath -match '^[A-Za-z]:/') {
337	    # Contracts persisted by predecessor gates record absolute paths of the
338	    # checkout that generated them. Relativize against the known repository
339	    # anchors so evidence stays verifiable from any checkout (issue #61).
340	    $anchorMatch = [Text.RegularExpressions.Regex]::Match(
341	      $normalizedPath, '^.*/(?<tail>(specs|reports|plugins)/.+)$')
342	    if (-not $anchorMatch.Success) { return $null }
343	    $normalizedPath = $anchorMatch.Groups['tail'].Value
344	  }
345	  if ($normalizedPath -match '(^|/)\.\.?(/|$)') { return $null }
346	  return $normalizedPath
347	}
348	# A round's verdict belongs to the text its two reviewers actually read: the
349	# two reviewers must have pinned the same hash for each reviewed document, and
350	# the contract must record that hash and no other. Mirrors
351	# lib/review-precheck-common.sh assert_contract_reviewer_agreement; the gap it
352	# closes (a contract recording a hash neither reviewer read) surfaced on
353	# epic-136-phase4-docs attempt 2 round 2.
354	function Assert-ContractReviewerAgreement([object]$Contract, [string]$Stage, [string]$FeatureName, [string]$RepoRoot) {
355	  $docKeys = @{ 'requirements.md' = 'requirements_sha256'; 'acceptance-tests.md' = 'acceptance_sha256'; 'design.md' = 'design_sha256' }
356	  foreach ($doc in @('requirements.md', 'acceptance-tests.md', 'design.md')) {
357	    $target = "specs/$FeatureName/$doc"
358	    $pinned = @{}
359	    foreach ($suffix in @('a', 'b')) {
360	      $role = "$Stage-reviewer-$suffix"
361	      $entries = @($Contract.reviewers |
362	        Where-Object { Test-OrdinalEqual $_.role $role } |
363	        ForEach-Object { $_.allowed_input_manifest } |
364	        Where-Object { Test-OrdinalEqual (Get-ManifestRelativePath ([string]$_.path) $RepoRoot) $target })
365	      $pinned[$suffix] = if ($entries.Count -ge 1) { [string]$entries[0].sha256 } else { '' }
366	    }
367	    if (-not $pinned['a'] -or -not $pinned['b']) { continue }
368	    if (-not (Test-OrdinalEqual $pinned['a'] $pinned['b'])) {
369	      Fail "persisted $Stage contract: reviewer-a and reviewer-b pinned different ${doc}; they did not review the same text"
370	    }
371	    $keyProp = $Contract.PSObject.Properties[$docKeys[$doc]]
372	    $contractHash = if ($null -ne $keyProp -and $null -ne $keyProp.Value) { [string]$keyProp.Value } else { '' }
373	    if ($contractHash -and -not (Test-OrdinalEqual $contractHash $pinned['a'])) {
374	      Fail "persisted $Stage contract records a ${doc} hash neither reviewer read; the verdict does not belong to that text"
375	    }
376	  }
377	}
