700	# for a colour-1 node proves a path from that node back to itself.
701	function Test-GraphHasCycleFrom { param([string]$Node,[hashtable]$Adjacency,[hashtable]$Visit)
702	  if ($Visit[$Node]) { return $false }
703	  $stack = [Collections.Generic.Stack[object[]]]::new()
704	  $stack.Push(@('enter', $Node))
705	  while ($stack.Count -gt 0) {
706	    $frame = $stack.Pop(); $op = $frame[0]; $current = $frame[1]
707	    if ($op -eq 'exit') { $Visit[$current] = 2; continue }
708	    if ($Visit[$current] -eq 1) { return $true }
709	    if ($Visit[$current] -eq 2) { continue }
710	    $Visit[$current] = 1
711	    $stack.Push(@('exit', $current))
712	    foreach ($next in $Adjacency[$current]) { $stack.Push(@('enter', $next)) }
713	  }
714	  return $false
715	}
